"use strict";(globalThis.webpackChunksanctuary_amongst_the_starts=globalThis.webpackChunksanctuary_amongst_the_starts||[]).push([[9053],{5534(e,t,s){s.r(t),s.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>n,toc:()=>h});const n=JSON.parse('{"id":"world-information/locations/outer-system/uranus","title":"Uranus","description":"---","source":"@site/docs/world-information/locations/outer-system/uranus.md","sourceDirName":"world-information/locations/outer-system","slug":"/world-information/locations/outer-system/uranus","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/uranus","draft":false,"unlisted":false,"editUrl":"https://github.com/kaelynj/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/uranus.md","tags":[],"version":"current","frontMatter":{},"sidebar":"loreSidebar","previous":{"title":"Titan","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/titan"},"next":{"title":"Extrasolar Systems","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/extrasolar-systems"}}');var a=s(4848),i=s(8453);const r={},o="Uranus",l={},h=[{value:"The Sideways",id:"the-sideways",level:2},{value:"Life Among the Clouds",id:"life-among-the-clouds",level:2},{value:"Settlements",id:"settlements",level:2},{value:"Varuna",id:"varuna",level:3},{value:"Uranian Moons",id:"uranian-moons",level:2},{value:"Oberon",id:"oberon",level:3},{value:"Titania",id:"titania",level:3},{value:"Xiphos",id:"xiphos",level:3}];function d(e){const t={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"uranus",children:"Uranus"})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Posted by:"})," ",(0,a.jsx)(t.em,{children:"Kristoffson, Firewall Proxy"})]}),"\n",(0,a.jsx)(t.p,{children:"Beyond Saturn's orbit, the Solar System turns into a sparsely populated wilderness with just a handful of large settlements and countless smaller ones. Uranus orbits at 10 AU beyond Saturn, and Neptune at 10 AU beyond that. The distances between stations and delta-v required to reach them is enormous, growing larger by measures the farther you travel. Life in the rimward system is both fragile and self-sufficient. It's a hodgepodge of brinkers, anarchists, romantics, scientists, and entrepreneurs -- sometimes all combined."}),"\n",(0,a.jsx)(t.h1,{id:"the-ice-giants",children:"The Ice Giants"}),"\n",(0,a.jsxs)(t.p,{children:["Uranus and Neptune are ice giants, comprised of water ice, methane, and ammonia with rocky cores. The resources mined by ",(0,a.jsx)(t.em,{children:"skimmers"})," on both worlds are vital to life beyond Saturn, from the water that keeps settlements alive to the volatiles used to fuel the freighters that plumb the outer trade routes."]}),"\n",(0,a.jsxs)(t.p,{children:["As the saying goes: ",(0,a.jsx)(t.em,{children:"it's a cold, rough life, but it beats inner-system bullshit"}),"."]}),"\n",(0,a.jsx)(t.h1,{id:"uranus-1",children:"Uranus"}),"\n",(0,a.jsx)(t.p,{children:"Uranus has the distinction of hosting most of the civilized settlements beyond Saturn. It's the last stop for comforts (and vices) before losing yourself in the final wilderness of Neptune and the Kuiper Belt. Most of transhumanity disregards Uranus as a boring backwater not worth the fuel it takes to match its odd orbit. Their loss. Uranus's oddness, and that of its inhabitants, is precisely what makes it beautiful."}),"\n",(0,a.jsx)(t.p,{children:"From a distance, Uranus is a stunning featureless greenish-blue. It's only when you get closer that you can appreciate the nuances in the clouds, the glittering ring fragments, and the jewel-like moons."}),"\n",(0,a.jsx)(t.h2,{id:"the-sideways",children:"The Sideways"}),"\n",(0,a.jsx)(t.p,{children:"Uranus's equator is inclined ~98 degrees to its orbit. Uranus's magnetic field is inclined ~60 degrees as well, though it's far weaker than Jupiter's or Saturn's, making life among the clouds a relative cakewalk. Orbital insertion around Uranus requires a short, furious burn that challenges even the best of pilots (who still require software assistance). It's one of the reasons Uranus remains remote and largely unsettled."}),"\n",(0,a.jsx)(t.h2,{id:"life-among-the-clouds",children:"Life Among the Clouds"}),"\n",(0,a.jsx)(t.p,{children:"Uranus is perfect for supporting aerostats and the local culture of skimmers have turned harvesting volatiles into a cottage industry. Without strong radiation or winds, these aerostats bumble happily along, converting Uranus into useful materials. They range in size from a few dozen people to single-person operations."}),"\n",(0,a.jsx)(t.p,{children:"Skimmers like their privacy, but if you let them engage you in conversations, you'll be opening yourself up to dubious stories of daring-do, plausible tales of escaping the authorities, or yarns about shapes in the clouds. Nearly every skimmer has at least one story of a strange heat source, sighting of an off-record ship or aerostat, or something even odder floating among the methane plumes."}),"\n",(0,a.jsx)(t.h2,{id:"settlements",children:"Settlements"}),"\n",(0,a.jsx)(t.h3,{id:"varuna",children:"Varuna"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Habitat Type:"})," Aerostat"]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Allegiance:"})," Brinker"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Varuna is Uranus's only large aerostat. It's run by an elected council and acts as a hub for skimmers. A few hypercorps maintain small offices here, trading for volatiles. Visitors find Varuna either provincial or charming."}),"\n",(0,a.jsx)(t.p,{children:"Several independent and hypercorp-controlled science labs have set up shop on Varuna. One major research project is an attempt to adapt pre-Fall Earth life to create oxygen-free biomes on gas giants. Success would open the colonizable area in the Solar System by several magnitudes."}),"\n",(0,a.jsx)(t.h2,{id:"uranian-moons",children:"Uranian Moons"}),"\n",(0,a.jsx)(t.p,{children:"Uranus has six significant satellites and several tiny moonlets in increasingly eccentric orbits. The main moons orbit around the planet's tilted equator, which means intercepting them from the system's elliptic takes a hell of a lot of fuel and skill. Most Uranian moons are sparsely inhabited. Due to their inclination, the smaller moonlets may be the last uninhabited places in the system."}),"\n",(0,a.jsx)(t.h3,{id:"oberon",children:"Oberon"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Allegiance:"})," Anarchist"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"8,000 of Oberon's 10,000 inhabitants live in Chat Noir, a frontier outpost run by a handful of anarchist collectives. It has advanced resleeving, egocasting, and manufacturing facilities, primarily to service the Fissure Gate, the only pandora gate in anarchist control. The gate's discovery transformed Chat Noir from a backwater to a boomtown overnight. So far, the Consortium has been unable to take control of the gate from the anarchists, and Chat Noir's security keeps it that way."}),"\n",(0,a.jsx)(t.p,{children:"The Cobweb is one of the premier farcasting facilities in the Solar System, taking advantage of Oberon's distant orbit from Uranus's interfering magnetosphere to egocast nearly anywhere. The facility is mobile, crawling across Oberon's surface on spider-like legs to achieve maximum signal fidelity. The Chat Noir collectives control Cobweb and only those with a high enough @-rep can use it."}),"\n",(0,a.jsx)(t.p,{children:"The Consortium and various hypercorps, tired of dealing with the anarchists' security measures and Chat Noir's lack of more luxurious amenities, have started prospecting to build a second spaceport on Oberon."}),"\n",(0,a.jsx)(t.h3,{id:"titania",children:"Titania"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Allegiance:"})," Anarchist/Brinker/Hypercorp"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Titania is synonymous with Xtreme sports, high-end holidays, and media glitz. It started as another autonomist prospector camp, until bored kids began diving from Messina Chasma, one of the largest canyons in the system. Titania's low gravity means the 0.5-kilometer fall takes a full 51 seconds, and an elastic carbon-fiber cable allows easy return to the base."}),"\n",(0,a.jsx)(t.p,{children:"A few grainy videos hitting the mesh was all it took for media hypercorps to leap on the commercial possibilities. Now the moon is a resort for inner-system glitterati interested in frontier fun. Most of Titania's settlements ring Messina Chasma."}),"\n",(0,a.jsx)(t.p,{children:"The settlement Crossing is the de-facto Xtreme sports headquarters because it hosts the 5-kilometer bridge that crosses the canyon. It's a classic rural resort town with surprisingly luxurious amenities, from its resleeving facility to its drinking, dining, and sex dens."}),"\n",(0,a.jsx)(t.h3,{id:"xiphos",children:"Xiphos"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Habitat Type:"})," Hamilton Cylinder"]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Allegiance:"})," Ultimates"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"At a length of 5.5 kilometers and diameter of 1 kilometer, Xiphos is one of the largest and best-apportioned habitats outside of the Main Belt. It began its life as an O'Neill cylinder before Manu Bhattacharya invested to upgrade it and tow it from Saturn to the Uranian rings. It's now a research and manufacturing facility where ultimate scientists develop advanced weaponized morphs and technologies. Any attempt to reach Xiphos by unauthorized approach is met with extreme and deadly resistance."}),"\n",(0,a.jsx)(t.p,{children:"What most outsiders know of Xiphos comes from their annual, three-day Olympics events. Held in the Greek tradition, these games are broadcast across the mesh, but entrance is limited only to Ultimates who can afford the high-end morphs they're showing off."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,s){s.d(t,{R:()=>r,x:()=>o});var n=s(6540);const a={},i=n.createContext(a);function r(e){const t=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);